// Walks all 300 trees of the real trained Random Forest and averages their votes
function forestPredict(row) {
  let total = 0;
  for (const tree of FOREST.trees) {
    let node = tree;
    while (!node.leaf) {
      node = row[node.f] <= node.thr ? node.l : node.r;
    }
    total += node.p;
  }
  return total / FOREST.trees.length;
}

